"""Build Loop 5.7 reports from the completed independent reconstruction.

All SHA-256 values in this script are calculated from file bytes at runtime.
It writes only under audit/loop5_7 and does not alter source or experiment files.
"""
from pathlib import Path
from datetime import datetime
import csv, hashlib, json, subprocess
import pandas as pd

ROOT=Path(__file__).resolve().parents[3]
OUT=ROOT/'audit'/'loop5_7'
FYP=Path(r'D:\Final Year Project')
L56=ROOT/'audit'/'loop5_6'
def sha(p):
    h=hashlib.sha256()
    with open(p,'rb') as f:
        for b in iter(lambda:f.read(1024*1024),b''):h.update(b)
    return h.hexdigest()
def readcsv(p):
    with open(p,newline='',encoding='utf-8-sig') as f:return list(csv.DictReader(f))
def writecsv(p,rows):
    fields=[]
    for r in rows:
        for k in r:
            if k not in fields:fields.append(k)
    with open(p,'w',newline='',encoding='utf-8') as f:
        w=csv.DictWriter(f,fieldnames=fields);w.writeheader();w.writerows(rows)
def git(cwd,*args):
    return subprocess.check_output(['git','-C',str(cwd),*args],text=True,stderr=subprocess.DEVNULL).strip()
def tracked(cwd,p):
    try: rel=str(Path(p).resolve().relative_to(Path(cwd).resolve())).replace('\\','/')
    except ValueError:return False
    return subprocess.run(['git','-C',str(cwd),'ls-files','--error-unmatch',rel],stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL).returncode==0

def main():
    cellp=OUT/'recomputed_cell_results.csv'; cells=readcsv(cellp)
    for r in cells:
        for k in ('mean_stability','mean_external_ari','mean_gap','mean_null_stability','saved_stability','saved_external_ari','saved_gap','saved_null_stability','stability_abs_error','ari_abs_error','null_abs_error','minimum_cluster_fraction'):
            r[k]=float(r[k])
        for k in ('n_successful_real_repeats','n_successful_null_repeats','n_pairwise_real_aris','n_pairwise_null_aris','nondegenerate_repeats_5pct','degenerate_repeats_5pct'):
            r[k]=int(r[k])
        for k in ('rule_i','rule_i_prime','rule_iii_method_recurrence','paired_same_protocol','all_status_success'):
            r[k]=str(r[k]).lower()=='true'
    # Rule (iii) has global requirements; preserve the per-cell recurrence flag
    # and annotate the overall mechanical condition separately.
    boot=json.loads((OUT/'bootstrap_reassessment.json').read_text(encoding='utf-8'))
    recurring={r['method'] for r in cells if r['rule_iii_method_recurrence']}
    recurrence_pass=len(recurring)>=3
    ci=boot['fresh_seed_on_nondegenerate_only']['percentile_95_ci']
    seq_ci=boot['same_rng_sequential_as_audit_degeneracy.py']['nondegenerate_cells']['percentile_95_ci']
    bootstrap_positive=ci[0]>0 and seq_ci[0]>0
    for r in cells:
        r['rule_iii_method_recurs_ge3_cohorts']=r['method'] in recurring and r['rule_i_prime']
        r['rule_iii_selected_cell']=r['rule_iii_method_recurs_ge3_cohorts']
        r['rule_iii_global_recurrence_condition']='MECHANICAL_PASS' if recurrence_pass else 'FAIL'
        r['rule_iii_global_bootstrap_condition']='POSITIVE_EXPLORATORY_CI_ESTIMAND_MISMATCH' if bootstrap_positive else 'FAIL'
        r['rule_iii_overall']='CONDITIONAL_EXPLORATORY' if recurrence_pass and bootstrap_positive else 'FAIL'
    # Create a final selection table from direct recomputations, not saved flags.
    writecsv(OUT/'nine_cell_final_verification.csv',cells)

    # Independent dataset-method benchmark summary and exact seed coverage.
    passf=FYP/'results'/'passF'/'benchmark_matrix_passF.csv'; cohirf=FYP/'results'/'exp3_cohirf_benchmark.csv'
    a=pd.read_csv(passf); b=pd.read_csv(cohirf)
    bench=pd.concat([a[['dataset','model','seed','ari']],b[['dataset','model','seed','ari']]],ignore_index=True)
    bm=bench.groupby(['dataset','model']).agg(n=('ari','size'),mean_ari=('ari','mean'),sd_ari=('ari','std'),median_ari=('ari','median'),seed_min=('seed','min'),seed_max=('seed','max')).reset_index()
    writecsv(OUT/'benchmark_dataset_method_means.csv',bm.to_dict('records'))
    summary=pd.read_csv(FYP/'results'/'passF'/'benchmark_matrix_summary_passF.csv')
    bm_pass=bm[bm.model!='CoHiRF'].rename(columns={'mean_ari':'mean_raw'})
    merged=summary.merge(bm_pass,on=['dataset','model'],suffixes=('_stored','_raw'),validate='one_to_one')
    max_mean_error=float((merged['mean']-merged['mean_raw']).abs().max())
    (OUT/'benchmark_summary_comparison.json').write_text(json.dumps({'passF_cells':len(merged),'max_abs_passF_cell_mean_error':max_mean_error,'passF_raw_rows':len(a),'cohirf_raw_rows':len(b),'combined_rows':len(bench),'unique_dataset_method_seed_keys':int(bench.drop_duplicates(['dataset','model','seed']).shape[0]),'combined_duplicate_keys':int(bench.duplicated(['dataset','model','seed']).sum()),'passF_seed_values_by_model':{m:sorted(map(int,g.seed.unique())) for m,g in a.groupby('model')},'cohirf_seed_values_by_dataset':{d:sorted(map(int,g.seed.unique())) for d,g in b.groupby('dataset')}},indent=2)+'\n',encoding='utf-8')

    # Final source-of-truth manifest; hashes are freshly calculated.
    manifest=[]
    loop56_files=sorted(p for p in L56.rglob('*') if p.is_file())
    stale={'recomputed_summary.json','evidence_recovery_inventory.csv','cohort_cache_inventory.csv','execution_manifest.json','provenance_manifest.csv','repository_state.md','benchmark_scope_consistency.md','cohort_evidence_recovery_report.md','loop5_6_final_adjudication.md','manuscript_claim_adjudication.csv','master_discrepancy_register.md'}
    def classify56(p):
        rel=p.relative_to(L56).as_posix(); name=p.name
        if name in stale:return 'Conflicting or misleading output'
        if name=='reconstruct_loop5_6.py':return 'Historical/superseded output'
        if name in ('finalize_reports.py',):return 'Conflicting or misleading output'
        if name.endswith('.zip'):return 'Unverified artifact'
        if rel.startswith('final_year_project_recovery/') and name in ('per_pair_stability.csv','per_repeat_results.csv','recomputed_cell_results.csv','recomputed_results.json','cohort_evidence_matrix.csv','hash_manifest.csv','file_inventory.csv','scan_metadata.json'):
            return 'Supporting evidence'
        if name in ('recomputed_stability_accuracy.csv','recomputation_comparison.csv','subset_reconstruction.csv','stability_accuracy_reconstruction.md','nine_cell_discrepancy_report.md'):
            return 'Authoritative final output'
        if name in ('statistical_validity_report.md','statistical_sensitivity_results.csv','cohort_and_method_results.csv','recomputed_summary.json'):
            return 'Historical/superseded output'
        if name in ('audit_fyp_evidence.py','build_minimum_package.py') or 'minimum_aggregate_package/' in rel:
            return 'Supporting evidence'
        if name=='clean_reproduction_test.json':return 'Supporting evidence'
        if name=='clean_reproduction_test.md':return 'Supporting evidence'
        if name=='duplicate_output_hashes.csv':return 'Supporting evidence'
        return 'Historical/superseded output'
    for p in loop56_files:
        st=p.stat(); manifest.append({'evidence_class':classify56(p),'path':str(p),'bytes':st.st_size,'modified_local':datetime.fromtimestamp(st.st_mtime).astimezone().isoformat(timespec='seconds'),'sha256':sha(p),'tracked_in_target_main':tracked(ROOT,p),'tracked_in_fyp_head':False,'source_commit':'Loop 5.6 deliverables commit 4fd21edaf7e4f45a8bea6acc8a052ad5f55275ba where tracked','generating_script':'varies; see audit_artifact_reconciliation.md','verification_note':'Loop 5.6 current bytes dynamically hashed'})
    # FYP relevant inventory from the earlier full recursive scan, re-hashed now.
    inv=readcsv(L56/'final_year_project_recovery'/'hash_manifest.csv')
    for row in inv:
        p=Path(row['path'].replace('/','\\'))
        try: st=p.stat(); actual=sha(p); exists=True
        except OSError: st=None;actual='';exists=False
        manifest.append({'evidence_class':row.get('classification','Unverified'),'path':str(p),'bytes':st.st_size if exists else row.get('size_bytes',''),'modified_local':datetime.fromtimestamp(st.st_mtime).astimezone().isoformat(timespec='seconds') if exists else row.get('modified_local',''),'sha256':actual or row.get('sha256',''),'tracked_in_target_main':False,'tracked_in_fyp_head':row.get('tracked_in_fyp_head',''),'source_commit':'local FYP repository; per-file history noted in provenance_chain.md','generating_script':'original/unknown; see provenance notes','verification_note':'SHA-256 dynamically recomputed in Loop 5.7' if exists else 'Not accessible at Loop 5.7 execution'})
    extras=[
      (FYP/'experiments/exp3_real_world_benchmarks/data/cache/cns.npz','tracked reference cache'),
      (FYP/'experiments/exp3_real_world_benchmarks/data/cache/colon.npz','tracked reference cache'),
      (FYP/'experiments/exp3_real_world_benchmarks/data/cache/leukemia.npz','tracked reference cache'),
      (FYP/'experiments/exp3_real_world_benchmarks/data/cache/ovarian.npz','tracked reference cache'),
      (FYP/'experiments/exp3_real_world_benchmarks/data/cache/prostate.npz','tracked reference cache'),
      (FYP/'experiments/exp3_real_world_benchmarks/data/cache/srbct.npz','tracked reference cache'),
      (passf,'13-dataset Pass F raw ARI rows'),(cohirf,'13-dataset CoHiRF raw ARI rows'),
      (FYP/'results/passF/benchmark_matrix_summary_passF.csv','pass F aggregate'),(FYP/'results/stats.json','12-method Friedman output'),
      (FYP/'results/passF/friedman_nemenyi_passF.json','earlier 11-method output'),
      (FYP/'scripts/run_phase3_experiments.py','CoHiRF experiment source'),(FYP/'scripts/make_stats.py','benchmark statistics source'),
      (FYP/'scripts/audit_degeneracy.py','degeneracy/bootstrap source'),
      (ROOT/'paper/manuscript/main.tex','current local manuscript; ignored/untracked'),
      (OUT/'zenodo_record_snapshot.json','Zenodo metadata snapshot')]
    for p,desc in extras:
        if not p.is_file():continue
        st=p.stat();manifest.append({'evidence_class':desc,'path':str(p),'bytes':st.st_size,'modified_local':datetime.fromtimestamp(st.st_mtime).astimezone().isoformat(timespec='seconds'),'sha256':sha(p),'tracked_in_target_main':tracked(ROOT,p),'tracked_in_fyp_head':tracked(FYP,p),'source_commit':'see provenance_chain.md','generating_script':'original source or checked-in artifact','verification_note':'SHA-256 dynamically calculated'})
    writecsv(OUT/'source_of_truth_manifest.csv',manifest)
    source_manifest_rows=len(manifest)

    # Parse repository identities from the actual checkouts.
    head=git(ROOT,'rev-parse','HEAD'); remote=git(ROOT,'rev-parse','origin/main'); fhead=git(FYP,'rev-parse','HEAD')
    paper=ROOT/'paper/manuscript/main.tex'; paper_sha=sha(paper)
    cache_checks=[]
    for d in ('cns','colon','leukemia','ovarian','prostate','srbct'):
        p1=FYP/'data/cache'/f'{d}.npz';p2=FYP/'experiments/exp3_real_world_benchmarks/data/cache'/f'{d}.npz'
        cache_checks.append((d,sha(p1),sha(p2),sha(p1)==sha(p2)))
    summary=json.loads((OUT/'independent_reconstruction_summary.json').read_text(encoding='utf-8'))
    boot=json.loads((OUT/'bootstrap_reassessment.json').read_text(encoding='utf-8'))
    benchstat=json.loads((OUT/'benchmark_recalculation.json').read_text(encoding='utf-8'))
    nine=summary['rule_iii_nine']; nondeg=summary['nondegenerate_60_cells']
    l56_count=len(loop56_files)
    (OUT/'audit_artifact_reconciliation.md').write_text(f'''# Loop 5.6 artifact reconciliation\n\n## Repository and package identity\n\nAt Loop 5.7 start, target `HEAD=origin/main={head}`. It is the committed Loop 5.6 deliverables commit (2026-11-02 16:17:48 +05:30). Code-under-audit remains `313e1542d524ddd2b38fa8c7e2ae885f9c52b7ca`; Loop 5.6 deliverables commit is `4fd21edaf7e4f45a8bea6acc8a052ad5f55275ba`. The separate FYP worktree is at {fhead}. The target Loop 5.6 tree has **{l56_count} files** at this inspection (including the local aggregate ZIP, which is ignored/untracked and absent from a fresh clone). Every file is enumerated, dynamically hashed and classified in `source_of_truth_manifest.csv`.\n\n## Conflicting evidence state\n\nLoop 5.6 is not a single reproducible workflow state. The recorded order runs `audit_fyp_evidence.py`, then aggregate-only `reconstruct_loop5_6.py`, then package build and `finalize_reports.py`. The latter rewrites key CSVs from partition-level outputs but leaves `recomputed_summary.json` explicitly saying raw repeats are unavailable. It also rewrites `evidence_recovery_inventory.csv` with missing run/partition entries even though the nested FYP recovery contains them. Rerunning `reconstruct_loop5_6.py` last can replace the root-level partition-derived tables with aggregate-only tables while leaving narrative reports unchanged.\n\nThe most consequential stale or misleading files are: `recomputed_summary.json` (aggregate-only and explicitly says repeats unavailable); `evidence_recovery_inventory.csv` (marks recovered run/partition files missing); `cohort_cache_inventory.csv` (does not mention tracked byte-identical cache copies); `repository_state.md`, `provenance_manifest.csv`, `execution_manifest.json` (claim `49f3882...` as an execution commit, say final artifacts are uncommitted, and omit the now-published restricted zero-file DOI record); and `recovery_report.md` (calls the historical artifact commit an execution commit). `reconstruct_loop5_6.py` is an aggregate-only script, not the source for the final partition-level table. `finalize_reports.py` copies some aggregate-only sensitivity outputs and writes an incomplete inventory.\n\nThe `minimum_aggregate_package/README.md` statement that per-fit records are unavailable is only accurate about that aggregate-only package; it is false if generalized to the local audit environment. The local `minimum_aggregate_package.zip` was not committed and is not present in the clean clone. The tracked package directory reproduces aggregate arithmetic only.\n\n## Reconciliation result\n\nLoop 5.6's final cell table is numerically supported by the nested saved partitions and records: the Loop 5.7 independent implementation found 72/72 cells, 4,320/4,320 partitions and records, zero metadata/status/shape/split errors, and maxima of {summary['maximum_errors']['max_abs_stability_cell_error']:.3g} stability, {summary['maximum_errors']['max_abs_external_ari_cell_error']:.3g} external-ARI, and {summary['maximum_errors']['max_abs_null_stability_cell_error']:.3g} null-stability cell discrepancies. Those calculations do not authenticate the historical fit event.\n\nThe corrected source-of-truth hierarchy is: (1) raw local partition arrays, Parquet per-fit records, exact cache bytes and tracked reference-cache copies; (2) the independent Loop 5.7 outputs generated by `scripts/independent_reconcile.py`; (3) the original tracked aggregate summary and benchmark tables only as comparison targets; (4) Loop 5.6 prose/aggregate-only tables as historical explanatory artifacts, with the conflicting files above disavowed.\n\n## Determinism\n\nThe metric calculations are deterministic for fixed input bytes, Python/NumPy/scikit-learn/Pandas/SciPy behavior and stable iteration order. The original FYP full-tree inventory is not byte-deterministic because `os.walk` order and timestamps vary; report manifests include execution timestamps and absolute local paths. `finalize_reports.py` has hard-coded execution metadata and depends on the current root-file state. Therefore rerunning the listed Loop 5.6 sequence does not recreate a coherent byte-identical package. The Loop 5.7 machine manifest identifies the exact current bytes and calculation source.\n''',encoding='utf-8')

    (OUT/'authoritative_execution_workflow.md').write_text('''# Authoritative evidence workflow\n\n1. Start with target code commit `313e1542d524ddd2b38fa8c7e2ae885f9c52b7ca`; separately record the Loop 5.6 audit-deliverables commit `4fd21edaf7e4f45a8bea6acc8a052ad5f55275ba`. The exact original fit-execution commit is **UNVERIFIABLE**.\n2. Confirm the six FYP caches and all expected `results/stability/partitions` and `runs` files exist; calculate SHA-256 dynamically. Verify local `data/cache/*.npz` against the tracked `experiments/exp3_real_world_benchmarks/data/cache/*.npz` copies. Do not infer execution linkage from cache identity alone.\n3. Run `python audit/loop5_7/scripts/independent_reconcile.py` from a checkout where `D:\\Final Year Project` is present and required Python dependencies are installed. This independently reads all 4,320 partitions and 4,320 Parquet records; it performs no model fits and writes only beneath `audit/loop5_7/`.\n4. Run `python audit/loop5_7/scripts/build_final_deliverables.py`. It rebuilds source inventory/manifests and benchmark mean comparison from raw score CSVs. Do not run Loop 5.6 `reconstruct_loop5_6.py` after the partition-level reconciliation; it is aggregate-only and can overwrite root outputs.\n5. Review `independent_reconstruction_summary.json`, all 72 rows in `recomputed_cell_results.csv`, per-repeat observations, nine-cell sensitivity outputs, bootstrap reconciliation, and the benchmark raw-score checks. Then review the current manuscript claim matrix.\n6. Verify `SHA256SUMS` only after all output files are final. It is a digest list of Loop 5.7 deliverables; it is not a signature or proof of public availability.\n\n## Scope and reproducibility\n\nThis procedure reproduces metrics from saved partitions. It does **not** reproduce the clustering fits that produced the saved partitions. A fresh GitHub clone reproduces only aggregate CSV arithmetic through the tracked minimum-package script. The ZIP referenced by the Loop 5.6 test is ignored/untracked. A full independent clone+data-acquisition+fit rerun is not available.\n\nThe numeric algorithms are deterministic for fixed input bytes and software behavior; the Loop 5.6 scan manifests are not byte-deterministic because they include filesystem timestamps/order. The Loop 5.7 scripts include execution timestamps in summaries, so report bytes will change even when numeric calculations do not.\n''',encoding='utf-8')

    (OUT/'independent_reconstruction_report.md').write_text(f'''# Independent reconstruction report\n\n## Execution performed\n\nThe lead auditor independently executed `scripts/independent_reconcile.py` against local FYP inputs: 4,320 `results/stability/partitions/*.npy`, 4,320 `results/stability/runs/*.parquet`, six `data/cache/*.npz`, and the tracked `subsample_stability_summary.csv`. It loaded the stored assignments, recalculated each real and null pairwise intersection ARI, recalculated each repeat ARI against the cache labels, and checked fit-row fields by key. This is a **partition-level metric reconstruction**, not a fresh rerun of 4,320 model fits. Agent A independently calculated the same result.\n\n- Expected/found partition files: 4,320 / {summary['partition_files']}\n- Expected/found Parquet records: 4,320 / {summary['fit_records']}\n- Repeats parsed: {summary['repeat_rows']}\n- Pairwise stability comparisons: 62,640 = 72 × 435 × 2 modes\n- Failed fits: {summary['failed_fit_records']}\n- Malformed/status/metadata/size/index/split errors: {summary['malformed_or_failed_checks']}\n- Missing expected artifacts: partitions {summary['missing_partition_files']}; records {summary['missing_fit_records']}\n- Cross-method/mode split mismatches: 0; unique row splits per cohort: 30\n- Maximum cell errors versus stored summary: stability {summary['maximum_errors']['max_abs_stability_cell_error']:.3g}; ARI {summary['maximum_errors']['max_abs_external_ari_cell_error']:.3g}; null stability {summary['maximum_errors']['max_abs_null_stability_cell_error']:.3g}.\n\nAll 72 cells matched at floating-point precision. Mean stability={summary['aggregate']['mean_stability']:.10f}; mean external ARI={summary['aggregate']['mean_external_ari']:.10f}; mean cell gap={summary['aggregate']['mean_gap']:.10f}; median cell gap={summary['median_gap']:.10f}; mean null stability={summary['aggregate']['mean_null_stability']:.10f}. The gap is computed as each cell's mean of 435 pairwise intersection ARIs **minus** that cell's mean of 30 label ARIs, then equally averaged over 72 cells. The median is the median of those 72 cell gaps. Because the design is balanced, equal cell weighting equals equal dataset-first or method-first weighting. It is not a general calibrated “excess reproducibility” score.\n\nThe two cell summaries are matched at cohort, method and split protocol because they use the same 30 assignments. They are not one-to-one repeated observations: stability contains 435 dependent pair values and ARI contains 30 per-repeat values. The pairwise values reuse the same partitions and overlapping samples.\n\n## Authenticity and duplicate findings\n\nThe files are internally consistent, not cryptographically authenticated as the original execution. Run rows do not store cache SHA, input path, sample IDs or source commit. Six ignored `data/cache/*.npz` copies are byte-identical to tracked FYP reference copies under `experiments/exp3_real_world_benchmarks/data/cache/`; this establishes a recoverable cache version but does not attest which cache bytes each fit loaded.\n\nAcross 4,320 partition files there are 4,169 distinct binary hashes: 140 duplicate-hash groups affect 291 files (151 excess copies). Parquet records have zero duplicate binary hashes. Three duplicate groups cross real/null or method/mode outputs: CNS CoHiRF real/null repeat 17 (identical one-cluster-vs-47 labels); Prostate CoHiRF-null/CoreHalo-real repeat 5; Prostate StdCons-null/UngatedAC-real repeat 16. They are suspicious and require provenance/root-cause explanation; exact label identity alone does not establish corruption.\n\n## Weighting and conditional subsets\n\nAll 72 cells: gap mean .464274, median .448407. The 60 cells passing the post-hoc non-degeneracy screen have cell-weighted gap mean .485376 and median .464041. The 18 cells satisfying Rule(i′) across any method have means stability .720011, ARI .003873, gap .716138; that is **not** the manuscript's different “18 cells” shorthand. The manuscript's .638304 stability and .045733 ARI are the 18 cohort×method cells for the three recurrent methods FCAG/FCM/FastMVC across all six cohorts. Nine Rule(iii)-recurrence cells are listed in `nine_cell_final_verification.csv`; their mean stability .683764, ARI −.002853, gap .686617, median gap .666136.\n''',encoding='utf-8')

    # Additional report files below are concise and cite exact artifact paths.
    (OUT/'provenance_chain.md').write_text(f'''# Provenance chain\n\n| Stage | Evidence and identity | Finding |\n|---|---|---|\n| Code under audit | target Git commit `313e1542d524ddd2b38fa8c7e2ae885f9c52b7ca` | Verified code-state identity. |\n| Loop 5.6 deliverables | target HEAD/origin main `4fd21edaf7e4f45a8bea6acc8a052ad5f55275ba` | Verified published main commit; contains all Loop 5.6 files. |\n| Original protocol | FYP Git commit `330738037fcb7f4ec8537581051b856a63c2b0d5` | Protocol history verified; not execution evidence. |\n| Post-hoc Rule(i′) amendment | FYP Git commit `548d68d54bb42bac76f20908cda1ae9a671e5b60` | Occurred after observing Prostate CoreHalo collapse; post-hoc. |\n| Historical code+summary commit | FYP Git commit `49f3882fe5385913a9af1a5b89138c6ae6d95579` | Contains source/protocol/tracked summary and tracked reference cache copies; does **not** contain the ignored partition/run artifact grid. Do not call it the execution commit. |\n| Actual stability run | 4,320 NPY and 4,320 Parquet files in local FYP worktree | Internal result grid complete, but exact run date/commit/config/input digest not stored per row. **Original execution commit: UNVERIFIABLE.** |\n| Inputs | `D:\\Final Year Project\\data\\cache\\*.npz` and matching tracked `experiments/exp3_real_world_benchmarks/data/cache/*.npz` | Byte-identical hashes for all six; run-to-cache linkage remains conditional because run rows omit hashes/IDs. |\n| Stability reconstruction | `audit/loop5_7/scripts/independent_reconcile.py` | Independently recalculates assignments/metrics. It does not rerun model fits. |\n| 13-dataset benchmark raw scores | FYP `results/passF/benchmark_matrix_passF.csv` and `results/exp3_cohirf_benchmark.csv` | Tracked locally in the FYP Git history at commits 7f74f68… and 567c526…; record commits do not prove fit execution. Current target GitHub main does not contain these files. |\n| Current manuscript | `paper/manuscript/main.tex`, SHA ` {paper_sha}` | Locally present but ignored/untracked by target Git; exact reviewed manuscript is not identified by a public commit. |\n| Loop 5.7 execution | target checkout HEAD `{head}` | Scripts executed against this checkout; local execution manifest records current time. |\n| Loop 5.7 final deliverables | not committed | No Loop 5.7 commit was created. |\n\nCurrent FYP local branch HEAD is `{fhead}`; `git ls-remote --heads` does not expose its `research/dami-revision` branch (only target `main` was observed). This means FYP-tracked artifacts are not thereby proven publicly accessible. Hashes and timestamps for every recovered item are in `source_of_truth_manifest.csv`. SHA-256 and Git blob SHA-1 are distinct and not compared as equivalent.\n\nThe published Zenodo record named in the manuscript resolves to DOI `10.5281/zenodo.23852735`, but the API snapshot `zenodo_record_snapshot.json` reports `status=published`, `access_right=restricted`, and `files=[]`. Both GitHub releases v1.0.0 and v2.2.0 have zero assets. The DOI is a metadata record, not a downloadable reproduction archive.\n''',encoding='utf-8')

    (OUT/'clean_reproduction_report.md').write_text('''# Clean-clone reproduction report\n\nA fresh shallow clone of GitHub `main` was created at commit `4fd21edaf7e4f45a8bea6acc8a052ad5f55275ba` under a temporary audit path and then removed after the test. It lacked `data/cache/*.npz`, `results/stability/partitions/`, `results/stability/runs/`, `results/passF/benchmark_matrix_passF.csv`, `results/exp3_cohirf_benchmark.csv`, and the local ZIP. It also did not contain the ignored current manuscript.\n\nIn that clean clone, the tracked `audit/loop5_6/minimum_aggregate_package/reproduce_aggregate.py` ran successfully using the included aggregate CSV and the standard library. It reproduced 72-row arithmetic: mean stability 0.516586, external ARI 0.052312, gap 0.464274, median gap 0.448407. This is **aggregate arithmetic reproduction only**. The ZIP named by the Loop 5.6 test JSON is not in the commit; the tracked package directory is.\n\nNo dataset acquisition, hash validation of raw partitions, fresh clustering rerun, or output comparison for the 4,320 fits was possible from the clone. The recovered FYP branch is local and not advertised on the configured GitHub remote. Zenodo DOI files are restricted/empty. **Complete public reproduction: FAIL.**\n''',encoding='utf-8')

    (OUT/'benchmark_scope_verification.md').write_text(f'''# 13-dataset benchmark scope verification\n\nThis is a separate external-ARI benchmark, not the six-cohort stability analysis. The recovered files are `D:\\Final Year Project\\results\\passF\\benchmark_matrix_passF.csv` (2,750 ARI rows, 11 methods) plus `D:\\Final Year Project\\results\\exp3_cohirf_benchmark.csv` (250 CoHiRF rows). Together: **3,000 rows, 13 datasets, 12 methods, 156 complete dataset–method cells, zero duplicate dataset–method–seed keys**. Each of 72 cells has 30 rows and each of 84 cells has 10 rows. Six high-D datasets ×12×30=2,160; seven others ×12×10=840; total 3,000. No cell-mean missingness.\n\nUsing raw row ARIs, then averaging within dataset×method, the Friedman test gives χ²={benchstat['friedman_chi_square']:.12f}, df={benchstat['degrees_freedom']}, p={benchstat['p_value']:.12f}. ICC-v2 average rank={benchstat['ICC_v2_mean_rank']:.6f}, rank position {benchstat['ICC_v2_rank_position']} of 12. This reproduces the manuscript's rounded p=.40 and 3,000/12 count from the saved score rows. It does not prove the model fits were rerun in Loop 5.7 or that the files are public. The previous Loop 5.5 1,430-row/11-method result was an earlier Pass E checkpoint; it is not the current full Pass F + CoHiRF evidence.\n\n**Seed/config inconsistency:** `benchmark_matrix_passF.csv` uses seed values 0–29 for high-D cells and 0–9 for other cells. `exp3_cohirf_benchmark.csv` uses 42–71 and 42–51. The target manuscript line 366 states the latter schedules for the omnibus benchmark; line 556 states 0–29/0–9 for CoHiRF, which contradicts its actual CSV and the historical `run_phase3_experiments.py` at commit 567c526 (42–71/42–51). The tracked raw score result commits are 7f74f68… and 567c526… respectively; neither is an execution attestation. The 12 method sample counts are equal per dataset, but seed identities are not matched across methods. Friedman uses dataset-level method means, so the reported statistic is reconstructible without treating seeds as matched pairs. Correct the manuscript's seed description and identify the precise raw inputs/configs.\n\n`friedman_nemenyi_passF.json` is an earlier 11-method N13 output (χ² 9.5944, p .4768); `results/stats.json` is the 12-method output. They must not be conflated. The broad benchmark says external-label ARI only; no stability–accuracy comparison is supported for all 13 datasets.\n''',encoding='utf-8')

